with src as (select *, initcap(trim(event_type)) as event_type_title from web_events where duration_sec between 140 and 192), summary as (select case when duration_sec >= 521 then 'high' when duration_sec >= 114 then 'mid' else 'low' end as duration_sec_bucket, count(distinct duration_sec) as unique_event_types, sum(duration_sec) as total_duration_sec from src group by case when duration_sec >= 521 then 'high' when duration_sec >= 114 then 'mid' else 'low' end) select * from summary order by unique_event_types desc, duration_sec_bucket limit 10
